function validStoredData(value, type){ if(!Array.isArray(value)) return false; if(type==='risks') return value.every(item=>Array.isArray(item)&&item.length>=7&&item.slice(0,7).every(field=>typeof field==='string')); if(type==='checks') return value.every(item=>item&&typeof item==='object'&&typeof item.title==='string'&&typeof item.detail==='string'&&typeof item.state==='string'); return value.every(item=>item&&typeof item==='object'&&item.id!==undefined&&typeof item.title==='string'&&typeof item.status==='string'); }
