function loadHospitalData(){const defaults=hospitals[activeHospital]?.imported?{risks:[],checks:[],actions:[]}:hospitalDemoData[activeHospital]||hospitalDemoData.santa;if(activeHospital!=='santa'&&!hospitals[activeHospital]?.imported&&localStorage.getItem(`aquaguard-${activeHospital}-demo-seeded`)!=='v2'){risks=cloneData(defaults.risks);checks=cloneData(defaults.checks);actions=cloneData(defaults.actions);saveData('risks',risks);saveData('checks',checks);saveData('actions',actions);localStorage.setItem(`aquaguard-${activeHospital}-demo-seeded`,'v2');}else{const storedRisks=readData('risks',defaults.risks),storedChecks=readData('checks',defaults.checks),storedActions=readData('actions',defaults.actions);risks=validStoredData(storedRisks,'risks')?storedRisks:cloneData(defaults.risks);checks=validStoredData(storedChecks,'checks')?storedChecks:cloneData(defaults.checks);actions=validStoredData(storedActions,'actions')?storedActions:cloneData(defaults.actions);}ensureCompletedDemoAction();translateCurrentLanguage();}
