function renderHeatStrip(){const strip=$('#heat-monitoring-strip');if(!strip)return;if(!window.heatMetrics||window.heatMetrics.unavailable){strip.innerHTML='<div class="heat-strip-empty">Heat checks: live forecast unavailable.</div>';return;}const metrics=window.heatMetrics,days=metrics.days||[],status=metrics.status||metrics.liveStatus;strip.innerHTML=`<div class="heat-strip-heading"><strong>7-day heat check</strong><span>${status==='Normal'?'No reinforced cooling-tower or hot-water checks recommended.':'Reinforced cooling-tower and hot-water checks recommended on highlighted days.'}</span></div><div class="heat-strip-days">${days.map(day=>`<div class="heat-strip-day ${day.max>=30?'hot':''} ${day.max>=35?'alert':''}"><strong>${new Date(`${day.date}T12:00:00`).toLocaleDateString([], {weekday:'short'})}</strong><span>${Math.round(day.max)} °C</span>${day.max>=30?'<small>Check</small>':''}</div>`).join('')}</div>`;}
function renderHeatUnavailable(status){window.heatMetrics={unavailable:true,status};currentHeatStatus=status;currentHeatKey='Live figures unavailable';$('#heat-status-badge').textContent=status==='Heat alert'?'HEAT ALERT':status==='Heat watch'?'HEAT WATCH':'UNAVAILABLE';$('#heat-status-badge').className=`live-tag heat-${status==='Heat alert'?'alert':status==='Heat watch'?'watch':'normal'}`;const statusElement=$('#heat-status');if(statusElement)statusElement.textContent=status;$('#heat-explanation').textContent=status==='Normal'?'Live data unavailable. No hot days can be confirmed.':'Live figures unavailable. This preview shows how AquaGuard would respond to this heat level.';$('#heat-days').innerHTML='<div class="heat-unavailable">Live data unavailable</div>';$('#heat-fetched').textContent='Live data unavailable';$('#heat-fetched').classList.remove('drought-warning');syncHeatDecisions(status,{demo:true,unavailable:true});renderHeatStrip();renderDroughtSummary(currentDroughtStatus,currentDroughtKey);renderNotifications();}
function renderHeatResult(result,fetchedAt=result.fetchedAt,stale=false){const simulated=$('#heat-simulate').value,status=simulated==='live'?result.liveStatus:simulated,days=result.days.map(day=>({...day,hot:day.max>=30,alert:day.max>=35}));window.heatMetrics={...result,days,status};currentHeatStatus=status;currentHeatKey=status==='Normal'?'No hot days':`${days.filter(day=>day.max>=30).length} hot days ≥ 30 °C`;$('#heat-status-badge').textContent=status==='Heat alert'?'HEAT ALERT':status==='Heat watch'?'HEAT WATCH':'NORMAL';$('#heat-status-badge').className=`live-tag heat-${status==='Heat alert'?'alert':status==='Heat watch'?'watch':'normal'}`;const statusElement=$('#heat-status');if(statusElement)statusElement.textContent=status;$('#heat-explanation').textContent=status==='Normal'?'No forecast maximum reaches 30 °C in the next 7 days.':`${days.filter(day=>day.max>=30).length} day${days.filter(day=>day.max>=30).length===1?' is':'s are'} forecast at 30 °C or more; ${days.filter(day=>day.max>=35).length} reach 35 °C or more.`;$('#heat-days').innerHTML=days.map(day=>`<div class="heat-day ${day.hot?'hot':''} ${day.alert?'alert':''}"><strong>${new Date(`${day.date}T12:00:00`).toLocaleDateString([], {weekday:'short'})}</strong><span>${Math.round(day.max)} °C</span>${day.alert?'<small>Alert</small>':day.hot?'<small>Watch</small>':''}</div>`).join('');const fetched=$('#heat-fetched');fetched.textContent=stale?`Data may be outdated — last updated ${new Date(fetchedAt).toLocaleString([], {dateStyle:'medium',timeStyle:'short'})}`:`Data fetched: ${new Date(fetchedAt).toLocaleString([], {dateStyle:'medium',timeStyle:'short'})}`;fetched.classList.toggle('drought-warning',stale);syncHeatDecisions(status,{demo:simulated!=='live'});renderHeatStrip();renderDroughtSummary(currentDroughtStatus,currentDroughtKey);renderNotifications();}
async function renderHeatStatus(){const request=++heatRequest,hospital=hospitals[activeHospital];renderHeatLoading(hospital.city);const controller=new AbortController(),timeout=setTimeout(()=>controller.abort(),8000);try{const data=await fetchJson(heatUrl(hospital),controller.signal),days=(data.daily?.time||[]).slice(0,7).map((date,i)=>({date,max:Number(data.daily?.temperature_2m_max?.[i])})).filter(day=>Number.isFinite(day.max));if(days.length!==7)throw new Error('Incomplete forecast');const liveStatus=days.some(day=>day.max>=35)?'Heat alert':days.some(day=>day.max>=30)?'Heat watch':'Normal',result={liveStatus,days,fetchedAt:new Date().toISOString()};saveHeatCache(activeHospital,{metrics:result,fetchedAt:result.fetchedAt});if(request===heatRequest)renderHeatResult(result);}catch(error){if(request!==heatRequest)return;const simulated=$('#heat-simulate').value;if(simulated!=='live'){renderHeatUnavailable(simulated);return;}const cached=readHeatCache(activeHospital);if(cached)renderHeatResult(cached.metrics,cached.fetchedAt,true);else{window.heatMetrics={unavailable:true,status:'Normal'};currentHeatStatus='Unavailable';currentHeatKey='Live figures unavailable';$('#heat-status-badge').textContent='UNAVAILABLE';$('#heat-status-badge').className='live-tag heat-normal';$('#heat-status').textContent='Live data unavailable';$('#heat-explanation').textContent='Live data unavailable. Try again later.';$('#heat-days').innerHTML='<div class="heat-unavailable">Live data unavailable</div>';$('#heat-fetched').textContent='Live data unavailable';syncHeatDecisions('Normal',{demo:false,unavailable:true});renderHeatStrip();renderDroughtSummary(currentDroughtStatus,currentDroughtKey);renderNotifications();}}finally{clearTimeout(timeout);}}
new MutationObserver(()=>{if($('#heat-status')?.textContent!=='Checking')$('.heat-card')?.classList.remove('is-loading');}).observe($('.heat-card'),{childList:true,subtree:true});
let onboardingStep = 0;
function onboardingData(){ try { const data=JSON.parse(localStorage.getItem(`aquaguard-onboarding-${activeHospital}`) || '{}'); return data && typeof data==='object' && !Array.isArray(data) ? data : {}; } catch { return {}; } }
function saveOnboarding(data){ localStorage.setItem(`aquaguard-onboarding-${activeHospital}`, JSON.stringify(data)); }
function renderOnboarding(){
  const hospital = hospitals[activeHospital], data = onboardingData(), done = data.complete ? 4 : (data._step || 0);
  $('#onboarding-hospital-tag').textContent = hospital.name.toUpperCase();
  $('#onboarding-count').textContent = data.complete ? '✓' : `${Math.max(1, 4-done)}`;
  const labels = ['Site profile', 'Water system', 'Critical services', 'Safety team'];
  $('#onboarding-steps').innerHTML = labels.map((label,i)=>`<button class="onboarding-step ${i===onboardingStep?'active':''} ${i<done||data.complete?'done':''}" data-onboarding-step="${i}"><span>${i<done||data.complete?'✓':i+1}</span>${label}</button>`).join('');
  const panels = [
    `<p class="eyebrow">STEP 1 OF 4 · SITE PROFILE</p><h2>Tell us about ${hospital.short}.</h2><p class="lead">We use this to tailor site labels, reporting headers, and the starting compliance scope.</p><div class="onboarding-fields"><label>Hospital or clinic name<input data-onboarding="name" value="${data.name || hospital.name}" /></label><label>City<input data-onboarding="city" value="${data.city || hospital.city}" /></label><label>Number of beds / chairs<input data-onboarding="capacity" type="number" min="1" value="${data.capacity || hospital.beds}" /></label></div>`,
    `<p class="eyebrow">STEP 2 OF 4 · WATER SYSTEM</p><h2>Map the essential infrastructure.</h2><p class="lead">A simple starting map is enough. You can add detail later with your facilities team.</p><div class="onboarding-fields"><label>Primary water source<select data-onboarding="source"><option ${data.source==='Municipal supply'?'selected':''}>Municipal supply</option><option ${data.source==='Private borehole'?'selected':''}>Private borehole</option><option ${data.source==='Mixed supply'?'selected':''}>Mixed supply</option></select></label><label>Number of water-storage tanks<input data-onboarding="tanks" type="number" min="0" value="${data.tanks ?? 0}" /></label><label>Buildings or clinical areas<input data-onboarding="areas" value="${data.areas || 'Main building'}" /></label></div>`,
    `<p class="eyebrow">STEP 3 OF 4 · CRITICAL SERVICES</p><h2>Identify priority water uses.</h2><p class="lead">We will suggest relevant monitoring points and controls for the services you select.</p><div class="service-options">${['Dialysis','ICU / critical care','Sterilisation (CSSD)','Dental care','Cooling towers'].map(service=>`<label><input data-service="${service}" type="checkbox" ${(data.services || []).includes(service)?'checked':''} />${service}</label>`).join('')}</div>`,
    `<p class="eyebrow">STEP 4 OF 4 · SAFETY TEAM</p><h2>Choose the accountable lead.</h2><p class="lead">Invite the rest of the team later. This person receives the first monitoring and review reminders.</p><div class="onboarding-fields"><label>Water-safety lead<input data-onboarding="lead" value="${data.lead || hospital.user}" /></label><label>Lead email<input data-onboarding="leadEmail" type="email" value="${data.leadEmail || ''}" placeholder="name@hospital.org" /></label></div>`
  ];
  $('#onboarding-content').innerHTML = `<div class="onboarding-panel">${panels[onboardingStep]}<div class="dialog-actions"><button class="secondary" id="onboarding-back" ${onboardingStep===0?'disabled':''}>Back</button><button class="primary" id="onboarding-next">${onboardingStep===3?'Finish setup':'Continue'} <span>→</span></button></div></div>`;
  const source = data.source || 'Municipal supply', areas = data.areas || 'Main building', tanks = Number(data.tanks || 0), services = data.services?.length ? data.services : ['Critical clinical units'];
  const tankLabel = tanks ? `${tanks} storage tank${tanks === 1 ? '' : 's'}` : 'Direct distribution';
  $('#map-status').textContent = data.complete ? 'BASELINE READY' : 'DRAFT MAP';
  $('#onboarding-map').innerHTML = `<div class="map-node source"><span>◉</span><strong>${source}</strong><small>Water source</small></div><div class="map-connector"><i>→</i></div><div class="map-node site"><span>⌂</span><strong>${areas}</strong><small>${data.complete ? `${data.capacity || hospital.beds} beds / chairs` : 'Complete Quick start to add this information'}</small></div><div class="map-branch"><div class="map-connector"><i>↓</i></div><div class="map-node storage"><span>▣</span><strong>${tankLabel}</strong><small>Storage & distribution</small></div><div class="map-connector"><i>→</i></div><div class="map-node critical"><span>✚</span><strong>${services.join(' · ')}</strong><small>Critical units</small></div></div>`;
  document.querySelectorAll('[data-onboarding-step]').forEach(button=>button.onclick=()=>{onboardingStep=Number(button.dataset.onboardingStep);renderOnboarding();});
  $('#onboarding-back').onclick=()=>{if(onboardingStep){onboardingStep--;renderOnboarding();}};
  $('#onboarding-next').onclick=()=>{
    const next = onboardingData();
    document.querySelectorAll('[data-onboarding]').forEach(input=>next[input.dataset.onboarding]=input.value);
    if(onboardingStep===2) next.services=[...document.querySelectorAll('[data-service]:checked')].map(input=>input.dataset.service);
    next._step = Math.max(next._step || 0, onboardingStep + 1);
    if(onboardingStep===3){ next.complete=true; next.completedAt=new Date().toISOString(); saveOnboarding(next); document.querySelector('[data-page-target="onboarding"]')?.toggleAttribute('hidden',true); document.querySelector('[data-page="onboarding"]')?.toggleAttribute('hidden',true); renderOnboarding(); renderAssets(); toast(`${hospital.name} is ready for monitoring.`); showPage('dashboard'); return; }
    saveOnboarding(next); onboardingStep++; renderOnboarding();
  };
}
