function badge(level){ return `<span class="badge ${level === 'High' || level === 'Overdue' ? 'high' : level === 'Medium' ? 'medium' : 'low'}">${level}</span>`; }
function renderAssets(){ const hospital=hospitals[activeHospital],data=onboardingData(),summary=document.querySelector('.setup-summary'); if(summary){if(data.complete){const completed=data.completedAt?new Date(data.completedAt).toLocaleDateString([], {day:'numeric',month:'short',year:'numeric'}):'Previously completed';summary.innerHTML=`<div class="setup-complete"><div><h3>Setup complete ✓</h3><p>Completed ${completed} · ${data.name||hospital.name} · ${data.city||hospital.city} · ${data.capacity||hospital.beds} beds / chairs · ${data.source||'Municipal supply'} · ${data.tanks||0} storage tanks</p></div><a href="#onboarding" class="setup-edit" id="edit-setup">Edit setup</a></div>`;}else summary.innerHTML=`<article><small>HOSPITAL</small><strong>${hospital.name}</strong><span>${hospital.city} · Setup pending</span></article><article><small>REGULATORY SCOPE</small><strong>Priority hospital</strong><span>PSA review annually</span></article><article><small>WATER SAFETY TEAM</small><strong>4 assigned members</strong><span>Complete Quick start to add this information</span></article>`;document.querySelector('.reset-demo-setup')?.remove();document.querySelector('.remove-imported-hospital')?.remove();summary.insertAdjacentHTML('afterend',`<a href="#" class="reset-demo-setup" id="reset-demo-setup">Reset demo setup</a>${hospital.imported?'<a href="#" class="remove-imported-hospital" id="remove-imported-hospital">Remove this hospital</a>':''}`);$('#edit-setup')?.addEventListener('click',event=>{event.preventDefault();onboardingStep=0;renderOnboarding();showPage('onboarding');});$('#reset-demo-setup').onclick=event=>{event.preventDefault();localStorage.removeItem(`aquaguard-onboarding-${activeHospital}`);onboardingStep=0;renderHospital();showPage('assets');};$('#remove-imported-hospital')?.addEventListener('click',event=>{event.preventDefault();if(!window.confirm(`Remove ${hospital.name}?`))return;Object.keys(localStorage).filter(key=>key.startsWith(`aquaguard-${activeHospital}-`)||key===`aquaguard-onboarding-${activeHospital}`).forEach(key=>localStorage.removeItem(key));delete hospitals[activeHospital];saveImportedHospitals();activeHospital='santa';localStorage.setItem('aquaguard-hospital',activeHospital);renderHospital();showPage('assets');toast('Hospital removed');});} $('#asset-grid').innerHTML = assets.map(a=>`<article class="asset"><span>${a[0]}</span><h3>${a[1]}</h3><p>${a[2]}</p><small>${a[3]}</small></article>`).join(''); }
function renderRisks(){ $('#risk-table').innerHTML = risks.map(r=>`<tr><td><strong>${r[0]}</strong><small>${r[1]}</small>${r[7]?`<small class="live-trigger">${r[7]}</small>`:''}</td><td>${badge(r[2])}</td><td>${r[3]}</td><td><div class="owner"><span class="avatar">${r[4]}</span>${r[5]}</div></td><td>${r[6]}</td></tr>`).join(''); $('#risk-count').textContent = risks.filter(r=>r[2] !== 'Low').length; }
function renderChecks(){ $('#monitoring-list').innerHTML = checks.map((c,i)=>`<div class="monitoring-row"><div class="date-pill"><strong>${c.day}</strong><span>${c.mon}</span></div><div><h3>${c.title}</h3><p>${c.detail}</p>${activeHospital!=='santa'?'<small class="live-trigger">SIMULATED / DEMO</small>':''}</div>${badge(c.state)}${c.state==='Overdue'?`<button class="check-button" data-check="${i}">Complete</button>`:''}</div>`).join(''); const overdue=checks.filter(c=>c.state==='Overdue'); $('#overdue-total').textContent=overdue.length; $('#monitor-count').textContent=overdue.length; document.querySelectorAll('[data-check]').forEach(b=>b.onclick=()=>{checks[Number(b.dataset.check)].state='Complete'; persistAll(); renderChecks(); toast('Check recorded in the audit trail.');}); }
