$('#save-record').onclick=()=>{ const title=trimmedRequired($('#record-title'),'Please enter a title.'), detail=trimmedRequired($('#record-detail'),'Please enter an owner or location.'); if(!title || !detail || !$('#record-title').checkValidity() || !$('#record-detail').checkValidity()) return; if(entryType==='risk'){risks.push([title,detail,'Medium','Control measure to be defined','SM','Safety Manager','Review due']); renderRisks();} else {checks.unshift({day:'10',mon:'Sep',title,detail,state:'Scheduled'});renderChecks();} persistAll(); $('#entry-dialog').close(); $('#record-title').value='';$('#record-detail').value='';toast('Record saved successfully.');};
$('#export-plan').onclick=()=>{const hospital=hospitals[activeHospital],text=`Water Safety Plan (Plan Sanitario del Agua)\n${hospital.name}\n${hospital.city}\nGenerated: ${today().toLocaleString()}\n\nMonitoring readings: ${hospital.readings}\nResults within thresholds: ${hospital.within}\nOpen exceptions: ${actions.filter(action=>action.status!=='Resolved').length}\n\nThis demo document summarises the selected hospital's current Water Safety Plan workspace.`;const url=URL.createObjectURL(new Blob([text],{type:'text/plain'})),link=document.createElement('a');link.href=url;link.download=`aquaguard-${activeHospital}-psa-document.txt`;link.click();URL.revokeObjectURL(url);};
$('#export-report').onclick=()=>{const open=actions.filter(a=>a.status!=='Resolved'),complete=checks.filter(c=>c.state==='Complete').length;const text=`AquaGuard compliance report\n${hospitals[activeHospital].name}\nGenerated: ${new Date().toLocaleString()}\n\nMonitoring checks complete: ${complete}/${checks.length}\nOpen corrective actions: ${open.length}\n\nOpen actions:\n${open.map(a=>`- ${a.title} (${a.severity}) — ${a.owner}`).join('\n')||'- None'}`;const url=URL.createObjectURL(new Blob([text],{type:'text/plain'})),link=document.createElement('a');link.href=url;link.download=`aquaguard-${activeHospital}-compliance-report.txt`;link.click();URL.revokeObjectURL(url);};
function toast(message){const el=$('#toast');el.textContent=message;el.className='show';setTimeout(()=>el.className='',2800);}
let actionFilters={bucket:'open',state:'all',severity:'all',owner:'all',origin:'all',query:''};
function actionOrigin(action){const source=(action.source||'').toLowerCase(),title=action.title.toLowerCase();return source.includes('heat')||source.includes('weather')||title.includes('heat')||title.includes('legionella risk')?'heat':source.includes('drought')||title.includes('drought')?'drought':'manual';}
function actionDate(action){const raw=(action.due||'').split(' · ')[0];return new Date(`${raw} ${today().getFullYear()}`);}
function actionMatches(action,overrideBucket=actionFilters.bucket){const open=action.status!=='Resolved',bucket=overrideBucket;if(bucket==='completed'&&!(!open))return false;if(bucket==='overdue'&&action.status!=='Overdue')return false;if(bucket==='due'&&!isDueToday(action))return false;if(bucket==='upcoming'&&(action.status==='Overdue'||isDueToday(action)))return false;if(actionFilters.state==='Critical'&&action.severity!=='Critical')return false;if(actionFilters.state==='Overdue'&&action.status!=='Overdue')return false;if(actionFilters.state==='Awaiting evidence'&&action.status!=='Awaiting evidence')return false;if(actionFilters.severity!=='all'&&action.severity!==actionFilters.severity)return false;if(actionFilters.owner!=='all'&&action.owner!==actionFilters.owner)return false;if(actionFilters.origin!=='all'&&actionOrigin(action)!==actionFilters.origin)return false;if(actionFilters.query&&!`${action.title} ${action.area} ${action.owner} ${action.source||''}`.toLowerCase().includes(actionFilters.query.toLowerCase()))return false;return true;}
function actionCard(action,completed=false){const origin=actionOrigin(action),originLabel=action.source&&action.source!=='SIMULATED / DEMO'?action.source:action.source?'Demo item':'';return `<article class="action-page-card ${action.status==='Overdue'?'overdue':''} ${completed?'completed-card':''}"><div class="action-card-head"><div><h3>${action.title}</h3><p>${action.area}</p></div>${badge(action.severity)}</div>${originLabel?`<small class="action-origin">${originLabel}</small>`:''}<div class="action-card-meta"><span><span class="avatar">${action.initials}</span>${action.owner}</span><span>${completed?`Resolved ${action.resolvedAt?new Date(action.resolvedAt).toLocaleDateString('en-GB',{day:'numeric',month:'short',year:'numeric'}):'this month'}`:`Due ${action.due}`}</span><strong>${completed?'Resolved':action.status}</strong></div>${completed?`<p class="resolution-note"><b>Resolved by:</b> ${action.resolvedBy||action.owner}<br /><b>Note:</b> ${action.resolutionNotes||'Action completed.'}<br /><b>Evidence:</b> ${action.evidence||'None attached'}</p><button class="text-button reopen-action" data-reopen-action="${action.id}">Reopen</button>`:`<button class="text-button open-action" data-action="${action.id}">Open →</button>`}</article>`;}
function renderActions(){const open=actions.filter(a=>a.status!=='Resolved'),overdue=open.filter(a=>a.status==='Overdue'),due=open.filter(isDueToday),upcoming=open.filter(a=>a.status!=='Overdue'&&!isDueToday(a)),completed=actions.filter(a=>a.status==='Resolved');$('#actions-count').textContent=open.length;$('#action-summary').innerHTML=`<button data-action-filter="critical"><strong>${open.filter(a=>a.severity==='Critical').length}</strong><span>critical actions</span></button><button data-action-filter="due"><strong>${due.length}</strong><span>due today</span></button><button data-action-filter="overdue"><strong>${overdue.length}</strong><span>overdue</span></button><button data-action-filter="awaiting"><strong>${open.filter(a=>a.status==='Awaiting evidence').length}</strong><span>awaiting evidence</span></button>`;$('#attention-list').innerHTML=open.slice().sort((a,b)=>actionDate(a)-actionDate(b)).map(a=>`<article class="action-row ${a.severity.toLowerCase()}"><div class="action-priority">${a.severity[0]}</div><div class="action-main"><strong>${a.title}</strong><small>${a.area}</small>${a.source?`<small class="live-trigger">${a.source}</small>`:''}<div class="action-meta">${badge(a.severity)} <span>Due ${a.due}</span><span class="owner"><span class="avatar">${a.initials}</span>${a.owner}</span></div></div><div class="action-state"><span>${a.status}</span><small>${a.escalation}</small></div><button class="text-button open-action" data-action="${a.id}">Open →</button></article>`).join('');$('#action-page-summary').innerHTML=[['overdue','Overdue',overdue.length],['due','Due today',due.length],['upcoming','Upcoming',upcoming.length],['completed','Completed this month',completed.filter(a=>!a.resolvedAt||new Date(a.resolvedAt).getMonth()===today().getMonth()).length]].map(x=>`<button class="card action-filter-tile ${actionFilters.bucket===x[0]?'active':''}" data-action-bucket="${x[0]}"><strong>${x[2]}</strong><span>${x[1]}</span></button>`).join('');const owners=[...new Set(actions.map(a=>a.owner))];$('#action-owner-filter').innerHTML='<option value="all">All owners</option>'+owners.map(o=>`<option ${actionFilters.owner===o?'selected':''}>${o}</option>`).join('');$('#action-severity-filter').value=actionFilters.severity;$('#action-origin-filter').value=actionFilters.origin;$('#action-search').value=actionFilters.query;const visibleOpen=actions.filter(actionMatches).filter(a=>a.status!=='Resolved').sort((a,b)=>a.status==='Overdue'?-1:b.status==='Overdue'?1:actionDate(a)-actionDate(b));const visibleDone=actions.filter(actionMatches).filter(a=>a.status==='Resolved').sort((a,b)=>new Date(b.resolvedAt||0)-new Date(a.resolvedAt||0));$('#actions-open-list').innerHTML=visibleOpen.length?visibleOpen.map(a=>actionCard(a)).join(''):'<div class="action-empty">No open or upcoming actions match these filters.</div>';$('#actions-completed-list').innerHTML=visibleDone.length?visibleDone.map(a=>actionCard(a,true)).join(''):'<div class="action-empty">No completed actions match these filters.</div>';document.querySelectorAll('.open-action').forEach(b=>b.onclick=()=>openAction(+b.dataset.action));document.querySelectorAll('[data-action-filter]').forEach(b=>b.onclick=()=>{actionFilters={...actionFilters,bucket:'open',state:b.dataset.actionFilter==='critical'?'Critical':b.dataset.actionFilter==='overdue'?'Overdue':b.dataset.actionFilter==='awaiting'?'Awaiting evidence':'all'};renderActions();showPage('actions');});document.querySelectorAll('[data-action-bucket]').forEach(b=>b.onclick=()=>{actionFilters={...actionFilters,bucket:b.dataset.actionBucket,state:'all'};renderActions();});document.querySelectorAll('[data-reopen-action]').forEach(b=>b.onclick=()=>{const action=actions.find(a=>a.id===Number(b.dataset.reopenAction));if(!action)return;action.status='Open';action.history+=` · Reopened by Laura Martín, ${today().toLocaleString()}`;saveData('actions',actions);renderActions();toast('Action reopened and returned to the open list.');});renderNotifications();}
function ensureActionFilterChip(){const filters=[];if(actionFilters.state!=='all')filters.push(actionFilters.state);else if(actionFilters.bucket!=='open')filters.push(actionFilters.bucket==='due'?'Due today':actionFilters.bucket[0].toUpperCase()+actionFilters.bucket.slice(1));if(actionFilters.severity!=='all')filters.push(actionFilters.severity);if(actionFilters.owner!=='all')filters.push(actionFilters.owner);if(actionFilters.origin!=='all')filters.push(actionFilters.origin[0].toUpperCase()+actionFilters.origin.slice(1));if(actionFilters.query)filters.push(`“${actionFilters.query}”`);let chip=$('#action-filter-chip');if(!chip){chip=document.createElement('div');chip.id='action-filter-chip';chip.className='action-filter-chip';$('#actions').querySelector('.actions-filters').insertAdjacentElement('afterend',chip);}const html=filters.length?`<span>Active filter: <strong>${filters.join(' · ')}</strong> ×</span><button type="button" id="clear-action-filters">Clear filters</button>`:'';if(chip.innerHTML!==html)chip.innerHTML=html;chip.hidden=!filters.length;$('#clear-action-filters')?.addEventListener('click',()=>{actionFilters={bucket:'open',state:'all',severity:'all',owner:'all',origin:'all',query:''};renderActions();});}
document.addEventListener('click',event=>{const card=event.target.closest('.action-page-card');if(card&&!event.target.closest('button'))openAction(Number(card.querySelector('[data-action]')?.dataset.action||card.querySelector('[data-reopen-action]')?.dataset.reopenAction));const filter=event.target.closest('[data-action-filter]');if(filter)setTimeout(()=>openActionsWithFilter({state:filter.dataset.actionFilter==='critical'?'Critical':filter.dataset.actionFilter==='overdue'?'Overdue':filter.dataset.actionFilter==='awaiting'?'Awaiting evidence':'all'}),0);});
document.addEventListener('keydown',event=>{const card=event.target.closest('.action-page-card');if(card&&(event.key==='Enter'||event.key===' ')){event.preventDefault();openAction(Number(card.querySelector('[data-action]')?.dataset.action||card.querySelector('[data-reopen-action]')?.dataset.reopenAction));}});
const actionObserver=new MutationObserver(()=>ensureActionFilterChip());actionObserver.observe($('#actions'),{childList:true,subtree:true});const actionCardObserver=new MutationObserver(()=>document.querySelectorAll('.action-page-card').forEach(card=>{card.tabIndex=0;card.setAttribute('role','button');card.setAttribute('aria-label',`Open action ${card.querySelector('h3')?.textContent||''}`);}));actionCardObserver.observe($('#actions'),{childList:true,subtree:true});
let selectedAction;function openAction(id){selectedAction=actions.find(a=>a.id===id);if(!selectedAction)return;$('#action-title').textContent=selectedAction.title;$('#resolve-action').hidden=selectedAction.status==='Resolved';$('#action-detail').innerHTML=`<div class="detail-grid"><p><b>Area / sampling point</b>${selectedAction.area}</p><p><b>Reading / observation</b>${selectedAction.reading}<br>${selectedAction.threshold}</p><p><b>Date and time</b>10 Sep 2026 · 08:12 CET</p><p><b>Operational consequence</b>${selectedAction.consequence}</p><p><b>Recommended corrective action</b>${selectedAction.recommendation}</p><p><b>Responsible person · deadline</b>${selectedAction.owner} · ${selectedAction.due}</p><p><b>Escalation</b>${selectedAction.escalation}</p><p><b>Activity history</b>${selectedAction.history}</p></div>`;$('#action-dialog').showModal();}$('#resolve-action').onclick=()=>{if(!selectedAction)return;$('#action-dialog').close();$('#resolve-dialog').showModal()};$('#save-resolution').onclick=()=>{const notes=trimmedRequired($('#resolution-notes'),'Please enter resolution notes.'),owner=trimmedRequired($('#resolution-owner'),'Please enter the responsible person.');if(!notes || !owner || !$('#resolution-notes').checkValidity() || !$('#resolution-owner').checkValidity() || !selectedAction)return;selectedAction.status='Resolved';selectedAction.resolvedAt=new Date().toISOString();selectedAction.resolvedBy=owner;selectedAction.resolutionNotes=notes;selectedAction.history+=` · Resolved by ${owner}, ${today().toLocaleString()}`;selectedAction.evidence=$('#evidence-file').files[0]?.name||'Action note recorded';saveData('actions',actions);$('#resolve-dialog').close();renderActions();toast('Action resolved and preserved in the audit trail.');};
function pdfLatin1(value){return String(value).replaceAll('€',String.fromCharCode(0x80)).replaceAll('–','-').replaceAll('—','-').replaceAll('…','...').replaceAll('·','-').replaceAll('≥','>=').replaceAll('°',' deg ').replace(/[\u0080-\uFFFF]/g,ch=>{const code=ch.charCodeAt(0);return String.fromCharCode(code===0xED?0xED:code===0xED?0xED:code<256?code:0x3F);});}
function pdfEscape(value){return pdfLatin1(value).replaceAll('\\','\\\\').replaceAll('(','\\(').replaceAll(')','\\)');}
function pdfByteLength(value){return [...pdfLatin1(value)].length;}
function makePdf(lines){const nl='\n',stream=['BT','/F1 11 Tf','50 760 Td',...lines.flatMap((line,index)=>[index?'0 -18 Td':'',`(${pdfEscape(line)}) Tj`]),'ET'].join(nl),objects=[`<< /Type /Catalog /Pages 2 0 R >>`,`<< /Type /Pages /Kids [3 0 R] /Count 1 >>`,`<< /Type /Page /Parent 2 0 R /MediaBox [0 0 612 792] /Resources << /Font << /F1 4 0 R >> >> /Contents 5 0 R >>`,`<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica /Encoding /WinAnsiEncoding >>`,`<< /Length ${pdfByteLength(stream)} >>${nl}stream${nl}${stream}${nl}endstream`];let pdf='%PDF-1.4'+nl,offsets=[];objects.forEach((object,index)=>{offsets[index]=pdfByteLength(pdf);pdf+=`${index+1} 0 obj${nl}${object}${nl}endobj${nl}`;});const xref=pdfByteLength(pdf);pdf+=`xref${nl}0 6${nl}0000000000 65535 f ${nl}${offsets.map(offset=>String(offset).padStart(10,'0')+' 00000 n '+nl).join('')}trailer${nl}<< /Size 6 /Root 1 0 R >>${nl}startxref${nl}${xref}${nl}%%EOF`;const bytes=new Uint8Array([...pdfLatin1(pdf)].map(char=>char.charCodeAt(0)));return new Blob([bytes],{type:'application/pdf'});}
function downloadPdf(filename,lines){const url=URL.createObjectURL(makePdf(lines)),link=document.createElement('a');link.href=url;link.download=filename;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function currentDataLabel(){const drought=$('#drought-simulate')?.value==='live'?'Live Open-Meteo data':'Demo preview - simulated drought level',heat=$('#heat-simulate')?.value==='live'?'Live Open-Meteo forecast':'Demo preview - simulated heat';return `Drought: ${currentDroughtStatus} (${drought}) | Heat: ${currentHeatStatus} (${heat})`;}
function reportPdfLines(){const hospital=hospitals[activeHospital],done=checks.filter(check=>check.state==='Complete').length,open=actions.filter(action=>action.status!=='Resolved'),completed=actions.filter(action=>action.status==='Resolved').length,setup=onboardingData();return ['AquaGuard compliance report',hospital.name,`${hospital.city} | Generated ${today().toLocaleString()}`,`Compliance score: ${hospital.score}`,`Checks: ${done}/${checks.length} complete | Open actions: ${open.length} | Completed actions: ${completed}`,currentDataLabel(),'','Quick start answers:',`Site: ${setup.name||hospital.name} | City: ${setup.city||hospital.city} | Beds/chairs: ${setup.capacity||hospital.beds}`,`Water source: ${setup.source||'Municipal supply'} | Tanks: ${setup.tanks??'0'} | Areas: ${setup.areas||'Main building'}`,`Safety lead: ${setup.lead||hospital.user}`,'','Open actions:',...(open.map(action=>`- ${action.title} | ${action.severity} | ${action.owner} | Due ${action.due}`)||['- None'])];}
$('#export-report').onclick=()=>downloadPdf(`aquaguard-${activeHospital}-compliance-report.pdf`,reportPdfLines());
$('#export-plan').onclick=()=>downloadPdf(`aquaguard-${activeHospital}-psa-document.pdf`,['Water Safety Plan (Plan Sanitario del Agua)',hospitals[activeHospital].name,`${hospitals[activeHospital].city} | Generated ${today().toLocaleString()}`,`Compliance score: ${hospitals[activeHospital].score}`,currentDataLabel(),'','Monitoring and corrective actions:',`Checks: ${checks.filter(check=>check.state==='Complete').length}/${checks.length} complete`,`Open actions: ${actions.filter(action=>action.status!=='Resolved').length} | Completed actions: ${actions.filter(action=>action.status==='Resolved').length}`,'','Quick start answers:',...Object.entries(onboardingData()).filter(([key])=>!key.startsWith('_')&&key!=='complete').map(([key,value])=>`${key}: ${value}`)]);
const pdfPalette={primary:'#126D70',text:'#17343A',secondary:'#4F6B70',normal:'#1F8A5B',watch:'#B7791F',alert:'#C2412D',demo:'#8A9A9D',surface:'#FFFFFF',background:'#F7F6F1',line:'#D9E4E1'};
const pdfRgb=hex=>[1,3,5].map(i=>parseInt(hex.slice(i,i+2),16));
const pdfStatusKey=value=>{const text=String(value||'').toLowerCase();return text.includes('alert')||text.includes('critical')||text.includes('overdue')||text.includes('high')?'alert':text.includes('watch')||text.includes('medium')||text.includes('due')?'watch':text.includes('demo')||text.includes('unavailable')?'demo':'normal';};
const pdfTint={normal:'#E5F3EC',watch:'#FFF4DD',alert:'#FBE7E3',demo:'#EEF1F1'};
function pdfDate(value=new Date()){const d=new Date(value);return `${d.getDate()} ${d.toLocaleDateString('en-GB',{month:'short'})} ${d.getFullYear()}, ${d.toLocaleTimeString('en-GB',{hour:'2-digit',minute:'2-digit',hour12:false})}`;}
function pdfText(value){return String(value??'').replaceAll('•','-').replaceAll('·',' | ').replaceAll('³','3').replaceAll('≥','>=').replaceAll('—',' - ').replaceAll('–','-').replaceAll('…','...');}
function pdfSection(doc,title,y){if(y>230){doc.addPage();y=20;}doc.setFont('helvetica','bold');doc.setFontSize(12);doc.setTextColor(...pdfRgb(pdfPalette.text));doc.text(pdfText(title),20,y);doc.setDrawColor(...pdfRgb(pdfPalette.primary));doc.setLineWidth(.35);doc.line(20,y+2,190,y+2);return y+9;}
function pdfPill(doc,label,x,y){const key=pdfStatusKey(label),text=pdfText(label),width=Math.max(18,doc.getTextWidth(text)+7);doc.setFillColor(...pdfRgb(pdfTint[key]));doc.setTextColor(...pdfRgb(pdfPalette[key]));doc.roundedRect(x,y-4,width,6,2,2,'F');doc.setFont('helvetica','bold');doc.setFontSize(7.5);doc.text(text,x+3,y);return width;}
function pdfHeader(doc,title){const h=hospitals[activeHospital];doc.setFillColor(...pdfRgb(pdfPalette.primary));doc.rect(0,0,210,39,'F');doc.setDrawColor(255,255,255);doc.setFillColor(255,255,255);doc.roundedRect(20,7,7,7,1.5,1.5,'F');doc.setLineWidth(.7);doc.line(21.5,10,25.5,10);doc.line(21.5,12,25.5,12);doc.setTextColor(255,255,255);doc.setFont('helvetica','bold');doc.setFontSize(13);doc.text('AquaGuard',30,15);doc.setFontSize(15);doc.text(pdfText(title),20,26);doc.setFont('helvetica','normal');doc.setFontSize(9);doc.text(pdfText(`${h.name} | ${h.city}`),20,33);doc.text(pdfDate(),190,33,{align:'right'});return 51;}
function pdfFooter(doc){const total=doc.getNumberOfPages();for(let page=1;page<=total;page++){doc.setPage(page);doc.setDrawColor(...pdfRgb(pdfPalette.line));doc.setLineWidth(.25);doc.line(20,282,190,282);doc.setFont('helvetica','normal');doc.setFontSize(7);doc.setTextColor(...pdfRgb(pdfPalette.secondary));doc.text(pdfText('AquaGuard · Demo prototype — illustrative hospital data; climate data from Open-Meteo and Eurostat'),20,289);doc.text(`Page ${page} of ${total}`,190,289,{align:'right'});}}
function pdfTable(doc,head,body,y,options={}){const estimate=Math.min(180,Math.max(24,body.length*7+18));if(y+estimate>270){doc.addPage();y=20;}const widths=head.length===6?{0:{cellWidth:18},1:{cellWidth:35},2:{cellWidth:36},3:{cellWidth:27},4:{cellWidth:24},5:{cellWidth:30}}:options.columnStyles;doc.autoTable({startY:y,head:[head],body,theme:'grid',margin:{left:20,right:20,bottom:20},tableWidth:170,styles:{font:'helvetica',fontSize:8,textColor:pdfRgb(pdfPalette.text),lineColor:pdfRgb(pdfPalette.line),lineWidth:.2,cellPadding:2,overflow:'linebreak'},headStyles:{fillColor:pdfRgb(pdfPalette.primary),textColor:[255,255,255],fontStyle:'bold'},alternateRowStyles:{fillColor:pdfRgb(pdfPalette.background)},...options,tableWidth:170,columnStyles:widths});return doc.lastAutoTable.finalY+10;}
function pdfStatusTableHook(data){if(data.section!=='body')return;const raw=pdfText(data.cell.raw);if(raw.includes('Critical')||raw.includes('High')||raw.includes('Medium')||raw.includes('Watch')||raw.includes('Alert')||raw.includes('Normal')||raw.includes('Resolved')||raw.includes('Overdue')){const key=pdfStatusKey(raw);data.cell.styles.textColor=pdfRgb(pdfPalette[key]);data.cell.styles.fillColor=pdfRgb(pdfTint[key]);data.cell.styles.fontStyle='bold';}}
function pdfKeyBoxes(doc,items,y){const width=39.5;items.forEach((item,index)=>{const x=20+index*42.5;doc.setFillColor(...pdfRgb(pdfPalette.background));doc.setDrawColor(...pdfRgb(pdfPalette.line));doc.roundedRect(x,y,width,20,2,2,'FD');doc.setFont('helvetica','bold');doc.setFontSize(16);doc.setTextColor(...pdfRgb(pdfPalette.text));doc.text(pdfText(item[0]),x+4,y+9);doc.setFont('helvetica','normal');doc.setFontSize(7);doc.setTextColor(...pdfRgb(pdfPalette.secondary));doc.text(pdfText(item[1]),x+4,y+16);});return y+29;}
function pdfClimate(doc,y){y=pdfSection(doc,'Climate conditions',y);const drought=$('#drought-status')?.textContent||currentDroughtStatus,heat=$('#heat-status')?.textContent||currentHeatStatus;const droughtOrigin=$('#drought-simulate')?.value==='live'?'Live Open-Meteo data':'Demo preview — simulated drought level',heatOrigin=$('#heat-simulate')?.value==='live'?'Live Open-Meteo forecast':'Demo preview — simulated heat';pdfPill(doc,drought,20,y);doc.setFont('helvetica','normal');doc.setFontSize(9);doc.setTextColor(...pdfRgb(pdfPalette.text));doc.text(pdfText(`Drought · ${currentDroughtKey} · ${droughtOrigin}`),48,y);pdfPill(doc,heat,20,y+10);doc.text(pdfText(`Heat · ${$('#heat-key')?.textContent||'7-day forecast'} · ${heatOrigin}`),48,y+10);doc.setFontSize(8);doc.setTextColor(...pdfRgb(pdfPalette.secondary));doc.text(pdfText(`European context: ${$('#eurostat-value')?.textContent||'Live data unavailable'} · ${$('#eurostat-detail')?.textContent||'dataset env_wat_abs'}`),20,y+21);return y+30;}
function pdfOpenRows(){return actions.filter(a=>a.status!=='Resolved').slice().sort((a,b)=>(a.status==='Overdue'?-1:1)-(b.status==='Overdue'?-1:1)||actionDate(a)-actionDate(b)).map(a=>[a.severity,a.title,a.area,a.owner,a.due,a.status]);}
function pdfCompletedRows(){return actions.filter(a=>a.status==='Resolved').slice().sort((a,b)=>new Date(b.resolvedAt||0)-new Date(a.resolvedAt||0)).map(a=>[a.title,a.resolvedBy||a.owner,a.resolvedAt?pdfDate(a.resolvedAt).split(',')[0]:'-',a.resolutionNotes||'Action completed.',a.evidence||'None attached']);}
function pdfCheckRows(){return checks.map(c=>[`${c.day} ${c.mon}`,c.title,c.state]);}
function pdfSetup(){const setup=onboardingData(),fallback='To be completed in Quick start',complete=setup.complete===true||setup.complete==='true';return {beds:complete?(setup.capacity||hospitals[activeHospital].beds):fallback,source:complete?(setup.source||fallback):fallback,storage:complete?(setup.tanks||fallback):fallback,buildings:complete?(setup.areas||fallback):fallback,critical:complete?(setup.services||fallback):fallback,lead:setup.lead||hospitals[activeHospital].user};}
function pdfRiskRows(){return risks.map(r=>[`${r[0]}${r[7]?` (${r[7]})`:''}`,r[1],r[2],r[3],`${r[5]} (${r[4]})`,r[6]]);}
function pdfLibrariesReady(){return typeof window.jspdf?.jsPDF==='function'&&typeof window.jspdf.jsPDF.API?.autoTable==='function';}
function exportProfessionalPdf(kind){if(!pdfLibrariesReady()){toast('PDF export is unavailable. Please check your connection and try again.');return;}try{const {jsPDF}=window.jspdf,doc=new jsPDF({unit:'mm',format:'a4'}),h=hospitals[activeHospital];let y=pdfHeader(doc,kind==='report'?'Compliance report':'Water Safety Plan (Plan Sanitario del Agua)');if(kind==='report'){y=pdfSection(doc,'Key figures',y);y=pdfKeyBoxes(doc,[[h.score,'Compliance score'],[`${checks.filter(c=>c.state==='Complete').length}/${checks.length}`,'Checks complete'],[actions.filter(a=>a.status!=='Resolved').length,'Open actions'],[actions.filter(a=>a.status==='Resolved').length,'Completed this month']],y);y=pdfClimate(doc,y);y=pdfSection(doc,'Open corrective actions',y);y=pdfTable(doc,['Severity','Title','Location','Owner','Due date','Status'],pdfOpenRows(),y,{didParseCell:pdfStatusTableHook,columnStyles:{0:{cellWidth:22},1:{cellWidth:40},2:{cellWidth:40},3:{cellWidth:28},4:{cellWidth:25},5:{cellWidth:25}}});y=pdfSection(doc,'Completed actions',y);y=pdfTable(doc,['Title','Resolved by','Date','Resolution note','Evidence'],pdfCompletedRows(),y,{didParseCell:pdfStatusTableHook});y=pdfSection(doc,'Monitoring checks',y);y=pdfTable(doc,['Date','Check','Status'],pdfCheckRows(),y,{didParseCell:pdfStatusTableHook});y=pdfSection(doc,'Data sources and limitations',y);doc.setFont('helvetica','normal');doc.setFontSize(9);doc.setTextColor(...pdfRgb(pdfPalette.secondary));doc.text(doc.splitTextToSize('Open-Meteo provides the rainfall, river discharge and weather forecast figures. Eurostat provides Spain freshwater abstraction context (dataset env_wat_abs). These figures support planning and are not official regulatory limits; regional examples such as Andalucía are not hospital measurements.',170),20,y);doc.textWithLink?.('Open-Meteo · https://open-meteo.com',20,y+22,{url:'https://open-meteo.com'});doc.textWithLink?.('Eurostat · dataset env_wat_abs',20,y+28,{url:'https://ec.europa.eu/eurostat/datasheet/env_wat_abs'});}else{y=pdfSection(doc,'Document control',y);doc.setFillColor(...pdfRgb(pdfPalette.background));doc.setDrawColor(...pdfRgb(pdfPalette.line));doc.roundedRect(20,y-5,170,31,2,2,'FD');const control=[['Hospital',h.name],['Version','1.4'],['Last updated',pdfDate()],['Review due date','15 Dec 2026'],['Water-safety lead',h.user]];control.forEach((item,index)=>{const x=index%2?108:24,yy=y+2+Math.floor(index/2)*8;doc.setFont('helvetica','bold');doc.setFontSize(7);doc.setTextColor(...pdfRgb(pdfPalette.secondary));doc.text(item[0],x,yy);doc.setFont('helvetica','normal');doc.setFontSize(8.5);doc.setTextColor(...pdfRgb(pdfPalette.text));doc.text(pdfText(item[1]),x,yy+4);});y+=36;y=pdfSection(doc,'Section 1 · Building and water system',y);const setup=pdfSetup();y=pdfTable(doc,['Answer','Selected hospital information'],[['Beds / chairs',setup.beds],['Water source',setup.source],['Storage',setup.storage],['Buildings / areas',setup.buildings],['Critical services',setup.critical]],y);y=pdfSection(doc,'Section 2 · Risk assessment',y);y=pdfTable(doc,['Hazard','Location','Level','Control measure','Owner','Review date'],pdfRiskRows(),y,{didParseCell:pdfStatusTableHook});y=pdfSection(doc,'Section 3 · Monitoring and corrective actions',y);doc.setFont('helvetica','normal');doc.setFontSize(9);doc.setTextColor(...pdfRgb(pdfPalette.text));doc.text(`Checks complete: ${checks.filter(c=>c.state==='Complete').length}/${checks.length} · Open actions: ${actions.filter(a=>a.status!=='Resolved').length} · Completed actions: ${actions.filter(a=>a.status==='Resolved').length}`,20,y);y+=7;y=pdfTable(doc,['Severity','Title','Location','Owner','Due date','Status'],pdfOpenRows(),y,{didParseCell:pdfStatusTableHook});y=pdfSection(doc,'Section 4 · Verification and approval',y);doc.setFont('helvetica','normal');doc.setFontSize(9);doc.text('Status: Pending management approval',20,y);doc.text('Name: ____________________    Role: ____________________    Date: ____________________',20,y+10);doc.roundedRect(20,y+17,75,25,2,2,'S');doc.setFontSize(8);doc.setTextColor(...pdfRgb(pdfPalette.secondary));doc.text('Signature',24,y+23);}pdfFooter(doc);doc.save(`aquaguard-${activeHospital}-${kind==='report'?'compliance-report':'psa-document'}.pdf`);}catch(error){console.error(error);toast('PDF export failed. Please try again.');}}
$('#export-report').onclick=()=>exportProfessionalPdf('report');$('#export-plan').onclick=()=>exportProfessionalPdf('plan');
const eurostatCacheKey=()=>`aquaguard-${activeHospital}-eurostat-cache`,eurostatUrl='https://ec.europa.eu/eurostat/api/dissemination/statistics/1.0/data/env_wat_abs?geo=ES&wat_proc=ABS_PWS&unit=M3_HAB&lang=en';
function renderEurostatCard(){let card=$('#eurostat-card');if(!card){document.querySelector('.context-grid').insertAdjacentHTML('afterend','<section class="card public-data-card" id="eurostat-card"><div class="card-title"><div><p class="eyebrow">CLIMATE RISKS</p><h2>European water-use context</h2></div><span class="live-tag" id="eurostat-badge">LIVE</span></div><p id="eurostat-series">Spain - freshwater abstraction for public water supply</p><strong id="eurostat-value">Loading...</strong><p id="eurostat-detail">Fetching Eurostat data...</p><small id="eurostat-fetched">Data fetched: -</small><a href="https://ec.europa.eu/eurostat/datasheet/env_wat_abs" target="_blank" rel="noreferrer">Eurostat dataset env_wat_abs -></a></section>');}card=$('#eurostat-card');card.querySelector('#eurostat-badge').textContent='LIVE';card.querySelector('#eurostat-value').textContent='Loading...';card.querySelector('#eurostat-detail').textContent='Fetching Eurostat data...';card.querySelector('#eurostat-fetched').textContent='Data fetched: -';card.classList.add('eurostat-loading');}
function eurostatCached(){try{const data=JSON.parse(localStorage.getItem(eurostatCacheKey())||'null');return data&&Number.isFinite(data.value)&&data.unit&&data.year?{...data,unit:'m³ per person',year:data.year==='latest'?'2024':data.year}:null;}catch{return null;}}
function showEurostatResult(data,stale=false){const card=$('#eurostat-card');if(!card)return;card.classList.remove('eurostat-loading');$('#eurostat-badge').textContent=stale?'OUTDATED':'LIVE';$('#eurostat-badge').className=`live-tag ${stale?'eurostat-outdated':''}`;$('#eurostat-value').textContent=`${new Intl.NumberFormat('en-GB',{maximumFractionDigits:1}).format(data.value)} ${data.unit}`;$('#eurostat-detail').textContent=`Spain | public water supply | ${data.year} | dataset env_wat_abs`;$('#eurostat-fetched').textContent=stale?`Data may be outdated - last updated ${pdfDate(data.fetchedAt)}`:`Data fetched: ${pdfDate(data.fetchedAt)}`;}
async function loadEurostatWaterData(){renderEurostatCard();const controller=new AbortController(),timeout=setTimeout(()=>controller.abort(),8000);try{const response=await fetch(eurostatUrl,{signal:controller.signal});if(!response.ok)throw new Error('Eurostat request failed');const data=await response.json(),values=Object.entries(data.value||{}).filter(([,value])=>Number.isFinite(value));if(!values.length)throw new Error('No Eurostat value');const time=data.dimension?.time?.category?.index||{},latest=values.sort((a,b)=>(time[b[0]]??-1)-(time[a[0]]??-1))[0],year=Object.keys(time).find(key=>time[key]===(time[latest[0]]??-1))||'latest',result={value:latest[1],unit:'million m³',year,fetchedAt:new Date().toISOString()};localStorage.setItem(eurostatCacheKey(),JSON.stringify(result));showEurostatResult(result);}catch(error){const cached=eurostatCached();if(cached){showEurostatResult(cached,true);}else{$('#eurostat-card')?.classList.remove('eurostat-loading');$('#eurostat-badge').textContent='UNAVAILABLE';$('#eurostat-badge').className='live-tag';$('#eurostat-value').textContent='Live data unavailable';$('#eurostat-detail').textContent='Eurostat data could not be fetched.';$('#eurostat-fetched').textContent='Live data unavailable';}}finally{clearTimeout(timeout);}}
async function loadEurostatWaterData(){renderEurostatCard();const controller=new AbortController(),timeout=setTimeout(()=>controller.abort(),8000);try{const response=await fetch(eurostatUrl,{signal:controller.signal});if(!response.ok)throw new Error('Eurostat request failed');const data=await response.json(),values=Object.entries(data.value||{}).filter(([,value])=>Number.isFinite(value));if(!values.length)throw new Error('No Eurostat value');const time=data.dimension?.time?.category?.index||{},latest=values.sort((a,b)=>Number(b[0])-Number(a[0]))[0],year=Object.keys(time).at(-1)||'latest',result={value:latest[1],unit:'m³ per person',year,fetchedAt:new Date().toISOString()};localStorage.setItem(eurostatCacheKey(),JSON.stringify(result));showEurostatResult(result);}catch(error){const cached=eurostatCached();if(cached){showEurostatResult(cached,true);}else{$('#eurostat-card')?.classList.remove('eurostat-loading');$('#eurostat-badge').textContent='UNAVAILABLE';$('#eurostat-badge').className='live-tag';$('#eurostat-value').textContent='Live data unavailable';$('#eurostat-detail').textContent='Eurostat data could not be fetched.';$('#eurostat-fetched').textContent='Live data unavailable';}}finally{clearTimeout(timeout);}}
